#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ChargeOnSolar's .env in the repo root gets the SMTP settings. The TransIP key
# from scripts/setup-transip.sh (in deploy/proxy) adds Lettermint's DNS records.
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$ROOT_DIR/.env"
PROXY_ENV="$ROOT_DIR/deploy/proxy/.env"
KEY_FILE="$ROOT_DIR/deploy/proxy/transip.key"

# proxy_env KEY: a value from the proxy stack's .env (written by setup-transip.sh).
proxy_env() {
  local ENV_FILE="$PROXY_ENV"
  _existing "$1"
}

# transip_token: a short-lived read-write TransIP API token, as in setup-transip.sh.
transip_token() {
  local body signature response
  body=$(jq -cn --arg login "$TRANSIP_LOGIN" --arg nonce "$(openssl rand -hex 8)" \
    '{login: $login, nonce: $nonce, read_only: false, expiration_time: "5 minutes",
      label: ("setup-lettermint-" + $nonce), global_key: true}')
  signature=$(printf '%s' "$body" | openssl dgst -sha512 -sign "$KEY_FILE" | openssl base64 -A)
  response=$(curl -sS -X POST https://api.transip.nl/v6/auth \
    -H 'Content-Type: application/json' -H "Signature: $signature" --data "$body")
  jq -er '.token // empty' <<<"$response" 2>/dev/null && return 0
  warn "TransIP refused: $(jq -r '.error // .' <<<"$response" 2>/dev/null || printf '%s' "$response")" >&2
  return 1
}

# fqdn VALUE: VALUE lowercased, with exactly one trailing dot. TransIP appends
# the zone to a CNAME target without one.
fqdn() {
  local v
  v=$(tr '[:upper:]' '[:lower:]' <<<"$1")
  printf '%s.' "${v%.}"
}

# relative_name NAME: NAME without ".$DOMAIN" (and a trailing dot), as TransIP
# wants it: Lettermint may show "lm1._domainkey" or "lm1._domainkey.welbo.eu".
relative_name() {
  local v
  v=$(tr '[:upper:]' '[:lower:]' <<<"${1%.}")
  printf '%s' "${v%".$DOMAIN"}"
}

# add_cname NAME TARGET: adds the CNAME through the TransIP API, unless DNS
# already has it. Never replaces a record that points elsewhere.
add_cname() {
  local name="$1" target="$2" current response
  current=$(dig +short CNAME "$name.$DOMAIN" @ns0.transip.net | tail -n1)
  if [[ "$current" == "$target" ]]; then
    printf '  %s✓%s %s.%s already points to %s\n' "$GREEN" "$RESET" "$name" "$DOMAIN" "$target"
    return 0
  fi
  if [[ -n "$current" ]]; then
    warn "$name.$DOMAIN already points to $current, not $target."
    warn "Fix it by hand in the TransIP control panel; this wizard won't replace it."
    return 1
  fi
  response=$(curl -sS -X POST "https://api.transip.nl/v6/domains/$DOMAIN/dns" \
    -H "Authorization: Bearer $TRANSIP_TOKEN" -H 'Content-Type: application/json' \
    --data "$(jq -cn --arg n "$name" --arg c "$target" \
      '{dnsEntry: {name: $n, expire: 3600, type: "CNAME", content: $c}}')" \
    -w '\n%{http_code}')
  if [[ "${response##*$'\n'}" == 2?? ]]; then
    printf '  %s✓ added%s %s.%s CNAME %s\n' "$GREEN" "$RESET" "$name" "$DOMAIN" "$target"
    return 0
  fi
  warn "TransIP didn't add $name: $(jq -r '.error // .' <<<"${response%$'\n'*}" 2>/dev/null)"
  return 1
}

run_wizard() {

TOTAL_STAGES=6

for tool in openssl jq curl dig node; do
  command -v "$tool" >/dev/null 2>&1 || { echo "This wizard needs $tool." >&2; exit 1; }
done
DOMAIN=$(proxy_env DOMAIN || true)
TRANSIP_LOGIN=$(proxy_env TRANSIP_LOGIN || true)
if [[ -z "$DOMAIN" || -z "$TRANSIP_LOGIN" || ! -f "$KEY_FILE" ]]; then
  echo "Run scripts/setup-transip.sh first: this wizard uses its TransIP key." >&2
  exit 1
fi

banner "Lettermint: Login codes by email from $DOMAIN"

stage "Account and project"
open_url "https://app.lettermint.co/register"
step "Sign up (the Free plan: 300 emails a month, 1 sending domain), or log in."
step "Under Projects, create a project, e.g. 'ChargeOnSolar'."
step "Make sure the project is Live, not Sandbox: Sandbox never delivers mail."
step "In the project's settings, switch on 'Enable SMTP'."
pause "Project created and SMTP on? Press Enter"

stage "Add $DOMAIN as a sending domain"
open_url "https://app.lettermint.co/domains"
step "Click 'Add domain' and enter $DOMAIN."
step "Open the domain's DNS page. Keep it open: the next stage needs its values."
dmarc=$(dig +short TXT "_dmarc.$DOMAIN" @ns0.transip.net | tr -d '"')
if [[ -n "$dmarc" ]]; then
  note "$DOMAIN already has a DMARC record, so skip Lettermint's DMARC record:"
  note "  $dmarc"
  if [[ "$dmarc" == *"aspf=s"* ]]; then
    warn "It has aspf=s, which Lettermint won't verify: change it to aspf=r in TransIP."
  fi
else
  warn "$DOMAIN has no DMARC record: add Lettermint's _dmarc TXT record in TransIP by hand."
fi
pause

stage "DNS records in TransIP"
say "Copy these from Lettermint's DNS page; the wizard adds them through the"
say "TransIP API. Names may be given with or without .$DOMAIN."
ask LM_DKIM1 "Target of lm1._domainkey (ends in .dkim.lmta.net):"
ask LM_DKIM2 "Target of lm2._domainkey (ends in .dkim.lmta.net):"
ask LM_BOUNCE_NAME "Name of the bounce record [Enter: lm-bounces]:"
ask LM_BOUNCE_TARGET "Target of the bounce record [Enter: bounces.lmta.net]:"
LM_BOUNCE_NAME=$(relative_name "${LM_BOUNCE_NAME:-lm-bounces}")
records=(
  "lm1._domainkey|$(fqdn "$LM_DKIM1")"
  "lm2._domainkey|$(fqdn "$LM_DKIM2")"
  "$LM_BOUNCE_NAME|$(fqdn "${LM_BOUNCE_TARGET:-bounces.lmta.net}")"
)
say ""
say "To add in $DOMAIN (TTL 1 hour):"
for r in "${records[@]}"; do note "  ${r%%|*} CNAME ${r#*|}"; done
if confirm "Add these to $DOMAIN's DNS at TransIP?"; then
  if TRANSIP_TOKEN=$(transip_token); then
    for r in "${records[@]}"; do
      add_cname "${r%%|*}" "${r#*|}" || SKIPPED+=("CNAME ${r%%|*}.$DOMAIN → ${r#*|} in TransIP")
    done
  else
    SKIPPED+=("Lettermint's 3 CNAME records in TransIP (the API refused the key)")
  fi
else
  say "Then add them by hand: TransIP → Domain → $DOMAIN → DNS, name without .$DOMAIN."
  pause "Added them? Press Enter"
fi
pause

stage "Verify the domain in Lettermint"
say "Checking that TransIP's name server answers with the new records."
for r in "${records[@]}"; do
  got=$(dig +short CNAME "${r%%|*}.$DOMAIN" @ns0.transip.net | tail -n1)
  if [[ "$got" == "${r#*|}" ]]; then
    printf '  %s✓%s %s.%s → %s\n' "$GREEN" "$RESET" "${r%%|*}" "$DOMAIN" "$got"
  else
    warn "${r%%|*}.$DOMAIN → ${got:-nothing yet}, expected ${r#*|}"
  fi
done
step "On Lettermint's DNS page for $DOMAIN, click 'Verify all'."
note "Records usually show up within minutes. If one stays pending, wait and"
note "click 'Verify all' again; the checks above show what TransIP serves."
pause "All records verified in Lettermint? Press Enter"

stage "SMTP credentials"
open_url "https://app.lettermint.co/projects"
step "Open your project → API Tokens → create a token, e.g. 'charge NUC'."
step "Copy it when it's shown (it starts with lm_). It's the SMTP password."
ask_secret SMTP_PASSWORD "Paste the project API token:"
[[ "$SMTP_PASSWORD" == lm_* ]] || warn "That doesn't start with lm_; check it's the project API token."
write_env SMTP_HOST "smtp.lettermint.co"
write_env SMTP_PORT "587"
write_env SMTP_USER "lettermint"
write_env SMTP_PASSWORD "$SMTP_PASSWORD"
ask MAIL_FROM "Sender [Enter: ChargeOnSolar <noreply@$DOMAIN>]:"
write_env MAIL_FROM "${MAIL_FROM:-ChargeOnSolar <noreply@$DOMAIN>}"
chmod 600 "$ENV_FILE"
pause

stage "Send a test email"
say "Sends a Login code email through the server's own mailer and these settings."
while :; do
  read -e -r -p "  ${BOLD}Send it to (your email address):${RESET} " test_to || break
  [[ -n "$test_to" ]] || continue
  if (cd "$ROOT_DIR/packages/server" && TEST_TO="$test_to" ENV_FILE="$ENV_FILE" node --input-type=module -e '
      import { createSmtpMailer, smtpSettings } from "./src/mailer.ts";
      process.loadEnvFile(process.env.ENV_FILE);
      await createSmtpMailer(smtpSettings.parse(process.env))
        .sendLoginCode({ to: process.env.TEST_TO, code: "123456" });
    '); then
    printf '  %s✓ sent%s: look for "123456 is your ChargeOnSolar login code" (check spam too).\n' "$GREEN" "$RESET"
    break
  fi
  warn "Sending failed (the error is above). Check: SMTP on for the project, the"
  warn "project Live, $DOMAIN verified, and the token copied whole."
  if ! confirm "Try again?"; then
    SKIPPED+=("A test email: re-run scripts/setup-lettermint.sh")
    break
  fi
done
pause

finish
note "The NUC needs these SMTP_* and MAIL_FROM lines in its .env too."
printf '\n'
}

run_wizard "$@"; exit
